  it('deletes the organization when its name is typed', async () => {
    const { user } = await renderSettings();
    const dialog = await openModal(user, 'Delete organization');
    await user.type(
      dialog.getByRole('textbox', { name: 'Organization name' }),
      'Analytical Engines'
    );

