import { SECTION_LABELS } from './constants';
import type { SectionKey } from './types';

export interface SettingsSectionForm {
  key: SectionKey;
  form: UseFormReturnType<any>;
}

interface SectionErrors {
  section: SettingsSectionForm;
  errors: FormErrors;
}

const showErrors = (title: string, failed: SectionErrors[]) => {
  const { section, errors } = failed[0];
  const path = Object.keys(errors)[0];
  path && section.form.getInputNode(path)?.focus();

  const labels = failed.map(({ section: { key } }) => SECTION_LABELS[key]).join(', ');
  notifications.show({ color: 'red', title, message: `Check the highlighted fields in ${labels}` });
};

export function useSaveSections(
  sections: SettingsSectionForm[],
  onSaved: (key: SectionKey, values: any) => void
) {
  const [saving, setSaving] = useState(false);

  const saveOne = async (section: SettingsSectionForm): Promise<SectionErrors | null> => {
    const { key, form } = section;
    try {
      const saved = await saveSection(key, form.getValues());
      // Saved values become the baseline for dirty checks and Cancel
      form.setInitialValues(saved);
      form.resetDirty(saved);
      onSaved(key, saved);
      return null;
    } catch (error) {
      if (error instanceof ServerValidationError) {
        form.setErrors(error.errors);
        return { section, errors: error.errors };
      }
      throw error;
    }
  };

  const save = async () => {
    const dirty = sections.filter(({ form }) => form.isDirty());
    const invalid = dirty
      .map((section) => ({ section, errors: section.form.validate().errors }))
      .filter(({ errors }) => Object.keys(errors).length > 0);

    if (invalid.length > 0) {
      showErrors('Changes not saved', invalid);
      return;
    }

    setSaving(true);
    const results = await Promise.all(dirty.map(saveOne));
    setSaving(false);

    const failed = results.filter((result) => result !== null);
    if (failed.length > 0) {
      showErrors('Some changes were not saved', failed);
      return;
    }

    const labels = dirty.map(({ key }) => SECTION_LABELS[key]).join(', ');
    notifications.show({ title: 'Changes saved', message: labels });
  };

  const cancel = () => {
    sections.forEach(({ form }) => form.isDirty() && form.reset());
  };

  return { saving, save, cancel };
}

import { hasLength, isEmail, isNotEmpty, isUrl, when } from '@mantine/form';
import { BIO_MAX_LENGTH } from './constants';
import type { BillingValues, NotificationsValues } from './types';

const requiredEmail = (requiredError: string) => (value: string) =>
  value.trim() === '' ? requiredError : isEmail('Enter a valid email address')(value.trim());

const optionalUrl = (value: string) =>
  value.trim() === ''
    ? null
    : isUrl('Enter a valid URL, for example https://example.com')(value.trim());

export const addressRules = {
  street: isNotEmpty('Enter a street'),
  city: isNotEmpty('Enter a city'),
  postalCode: isNotEmpty('Enter a postal code'),
  country: isNotEmpty('Select a country'),
};

export const profileRules = {
  fullName: isNotEmpty('Enter your full name'),
  email: requiredEmail('Enter your email'),
  bio: hasLength({ max: BIO_MAX_LENGTH }, `Bio must be ${BIO_MAX_LENGTH} characters or fewer`),
};

export const organizationRules = {
  name: isNotEmpty('Enter the organization name'),
  website: optionalUrl,
  address: addressRules,
};

const ownBillingAddress = (values: BillingValues) => !values.sameAsOrganization;

export const billingRules = {
  billingEmail: requiredEmail('Enter a billing email'),
  address: {
    street: when(ownBillingAddress, addressRules.street),
    city: when(ownBillingAddress, addressRules.city),
    postalCode: when(ownBillingAddress, addressRules.postalCode),
    country: when(ownBillingAddress, addressRules.country),
  },
};

export const hasDigestChannel = (values: NotificationsValues) =>
  Object.values(values.events.weeklyDigest).some(Boolean);

export const notificationsRules = {
  digestDay: when(hasDigestChannel, isNotEmpty('Select a digest day')),
};
